 ('mc', 5, 'veda_hutbe_yer', 'Veda Hutbesi', 'm', 'Veda Hutbesi’nin önemli bir kısmı nerede okundu?', 'Arafat’ta', ['Medine’de', 'Taif’te', 'Uhud’da'], 'Hz. Peygamber Arafat’ta büyük kalabalığa hitap etti.'),
 ('mc', 5, 'veda_canlar', 'Dokunulmazlık', 'm', 'Veda Hutbesi’ne göre hangileri birbirinize karşı dokunulmazdır?', 'Canlarınız, mallarınız ve namuslarınız', ['Sadece mallarınız', 'Sadece hayvanlarınız', 'Hiçbir şey'], '“Canlarınız, mallarınız ve namuslarınız bu günün, bu ayın, bu şehrin kutsallığı gibi dokunulmazdır.” (Buhârî)'),
 ('mc', 5, 'veda_ustunluk', 'Üstünlük', 'm', 'Veda Hutbesi’ne göre insanlar arasında üstünlük neyledir?', 'Takva ile', ['Soy ile', 'Renk ile', 'Zenginlik ile'], '“Arap’ın Arap olmayana, Arap olmayanın Arap’a üstünlüğü yoktur; üstünlük takvadadır.” (Ahmed b. Hanbel)'),
 ('mc', 5, 'kadin_hak', 'Kadın hakları', 'm', 'Veda Hutbesi’nde hangi konuda özellikle uyarıda bulunulmuştur?', 'Kadınların hakları konusunda Allah’tan korkmak', ['Ticaret vergileri', 'Savaş taktikleri', 'Saray kuralları'], '“Kadınların haklarına riayet etmenizi ve bu hususta Allah’tan korkmanızı tavsiye ederim.” (Müslim)'),
 ('mc', 5, 'maide3', 'Din kemale erdi', 'h', '“Bugün dininizi kemale erdirdim” âyeti hangi olay sırasında indi?', 'Veda Haccı’nda Arafat’ta', ['Bedir savaşında', 'Hendek kazılırken', 'Hicret yolunda'], 'Mâide 5:3, Veda Haccı’nda Arafat’ta inmiştir.'),
 ('mc', 5, 'vefat_yas', 'Vefatı', 'e', 'Hz. Peygamber kaç yaşında vefat etti?', '63', ['40', '53', '80'], 'Hz. Peygamber 632 yılında, 63 yaşında Medine’de vefat etti.'),
 ('mc', 5, 'vefat_yer', 'Kabri', 'm', 'Hz. Peygamber’in kabri nerededir?', 'Medine’de, Mescid-i Nebevî’nin yanında', ['Mekke’de, Kâbe’nin içinde', 'Kudüs’te', 'Taif’te'], 'Hz. Âişe’nin odasına defnedildi; bugün Mescid-i Nebevî’nin içindedir.'),
 ('tf', 5, 'ebubekir_hutbe', 'Hz. Ebû Bekir’in sözü', 'h', 'Hz. Peygamber vefat edince Hz. Ebû Bekir “Kim Muhammed’e kulluk ediyorsa bilsin ki o öldü; kim Allah’a kulluk ediyorsa bilsin ki Allah diridir, ölmez” dedi.', True, 'Hz. Ebû Bekir ardından Âl-i İmrân 3:144’ü okudu (Buhârî).'),
 ('tf', 5, 'emanet_iki', 'Bırakılan emanet', 'm', 'Veda Hutbesi’nde Hz. Peygamber ümmetine sarıldıkları sürece yolunu şaşırmayacakları bir emanet bıraktığını söyledi.', True, 'Rivayetlerde Allah’ın kitabı ve sünneti (ya da ehl-i beyti) olarak geçer.'),
 ('sc', 5, 'sc_irkcilik', 'Ayrımcılık', 'm', 'Okulda bir öğrenci farklı bir ülkeden geldiği için dışlanıyor. Veda Hutbesi’nin mesajı ne der?', 'Hiç kimsenin soyu veya rengi yüzünden üstünlüğü yoktur; üstünlük takvadadır', ['Bazı milletler doğuştan üstündür', 'Herkes yalnız kendi milletiyle arkadaş olmalı', 'Dışlamak doğaldır'], 'Veda Hutbesi ırk ve renk ayrımcılığını reddeder.'),
 ('sc', 5, 'sc_hak', 'Başkasının hakkı', 'm', 'Arkadaşının çantasından izinsiz bir şey almak “küçük bir şey” sayılabilir mi?', 'Hayır, başkasının malı dokunulmazdır', ['Evet, küçük şeyler sayılmaz', 'Evet, arkadaşsa sorun olmaz', 'Evet, kimse görmezse olur'], 'Veda Hutbesi malların dokunulmaz olduğunu vurgular.'),
 ('fb', 5, 'fb_632', 'Vefat yılı', 'm', 'Hz. Peygamber miladi ___ yılında vefat etti.', '632', ['622', '610', '571'], 'Hz. Peygamber 632’de vefat etti.'),
 ('fb', 5, 'fb_takva', 'Veda Hutbesi', 'e', 'Veda Hutbesi’ne göre üstünlük ancak ___ iledir.', 'takva', ['soy', 'servet', 'güç'], 'Üstünlük, Allah’a saygı ve sorumluluk bilinci olan takvadadır.'),
 ('mi', 5, 'mi_ravza', 'Ravza', 'h', 'Hz. Peygamber’in kabri ile minberi arasındaki alana ___ denir.', 'Ravza', ['Hatîm', 'Mültezem', 'Makam'], 'Hadiste bu alanın cennet bahçelerinden bir bahçe olduğu bildirilir (Buhârî).'),
 ('mt', 5, 'veda_esle', 'Veda Hutbesi', 'm', 'Veda Hutbesi’nin mesajlarını eşleştir:', [('Canlar ve mallar', 'Dokunulmazdır'), ('Üstünlük', 'Takvadadır'), ('Kadınlar', 'Haklarına riayet edilir'), ('Din', 'Kemale ermiştir')], 'Veda Hutbesi temel insan haklarını özetler.'),

 # S6 — Akıllı Tekrar (12)
 ('sr', 6, 'sr_bedir', 'Bedir', 'e', 'İlk büyük zafer hangi savaştır?', 'Bedir', ['Uhud', 'Hendek', 'Tebük'], 'Bedir, hicretin ikinci yılında kazanıldı.'),
 ('sr', 6, 'sr_bilal', 'Müezzin', 'e', 'İlk müezzin kimdir?', 'Bilâl', ['Ömer', 'Osman', 'Ali'], 'Hz. Bilâl ilk müezzindir.'),
