 ('sr', 6, 'sr_vefat', 'Vefat', 'm', 'Hz. Peygamber kaç yaşında vefat etti?', '63', ['40', '53', '70'], 'Altmış üç yaşında vefat etti.'),
 ('tf', 6, 'tf_tekrar_hendek', 'Hendek', 'm', 'Hendek fikrini Hz. Ömer verdi.', False, 'Hendek fikrini Selmân-ı Fârisî verdi.'),
