 ('tf', 6, 'tf_tekrar_hamza', 'Hamza', 'm', 'Hz. Hamza Bedir’de şehit oldu.', False, 'Hz. Hamza Uhud’da şehit oldu.'),
 ('mc', 6, 'mc_tekrar_ensar', 'Ensar', 'e', 'Muhacirlere kucak açan Medinelilere ne denir?', 'Ensar', ['Muhacir', 'Münafık', 'Mürted'], 'Ensar, yardım edenler demektir.'),
 ('mc', 6, 'mc_tekrar_hudeybiye', 'Antlaşma', 'm', 'Fetih Suresi’nde “apaçık fetih” denen antlaşma hangisidir?', 'Hudeybiye', ['Akabe', 'Medine Vesikası', 'Hılfu’l-fudûl'], 'Hudeybiye Antlaşması.'),
 ('mc', 6, 'mc_tekrar_veda', 'Veda Hutbesi', 'm', 'Veda Hutbesi’ne göre üstünlük neyledir?', 'Takva', ['Soy', 'Renk', 'Mal'], 'Üstünlük takvadadır.'),
 ('es', 6, 'es_tekrar_uhud', 'Uhud', 'm', 'Uhud’da okçular Hz. Peygamber’in emrine uyup yerlerinden ayrılmadılar.', 'Okçuların çoğu emre rağmen yerlerini bıraktı', ['Uhud’da hiç okçu yoktu', 'Okçular savaşa katılmadı', 'Uhud’da savaş olmadı'], 'Bu itaatsizlik ağır kayıplara yol açtı.'),
 ('es', 6, 'es_tekrar_fetih_savas', 'Fetih', 'm', 'Mekke’nin fethinde şehir büyük bir savaşla ele geçirildi.', 'Mekke büyük ölçüde kan dökülmeden fethedildi', ['Mekke hiç fethedilmedi', 'Mekke’yi Ebrehe fethetti', 'Mekke’nin fethi Medine’de oldu'], 'Fetih, af ve barış içinde gerçekleşti.'),

 # S7 — Ünite Challenge (14)
 ('sc', 7, 'ch_paylas', 'Yeni gelen', 'm', 'Sınıfınıza başka şehirden gelen bir öğrenci kimseyi tanımıyor. Ensar örneği ne öğretir?', 'Kucak açıp yardımcı olmayı, imkânları paylaşmayı', ['Onu kendi haline bırakmayı', 'Onunla alay etmeyi', 'Ondan uzak durmayı'], 'Ensar, muhacirleri kardeş bilip her şeylerini paylaştı.'),
 ('sc', 7, 'ch_istisare', 'Ortak karar', 'm', 'Sınıf başkanı önemli bir karar vermeden önce herkesin fikrini soruyor. Bu, Hz. Peygamber’in hangi uygulamasına uygundur?', 'İstişare', ['Kendi başına karar vermek', 'Kura çekmek', 'Hiç karar vermemek'], 'Hz. Peygamber Hendek’te ve başka pek çok konuda istişare etti.'),
 ('sc', 7, 'ch_bilgi', 'İlme değer', 'h', 'Bedir esirlerinin okuma yazma öğreterek serbest kalabilmesi neyi gösterir?', 'İslam’ın ilme ve eğitime verdiği değeri', ['Esirlerin önemsiz olduğunu', 'Okuma yazmanın gereksiz olduğunu', 'Savaşın tek amacın olduğunu'], 'Fidye olarak eğitimi kabul etmek, ilmin önemini gösterir.'),
 ('es', 7, 'ch_es_kible', 'İlk kıble', 'm', 'Müslümanların ilk kıblesi Mescid-i Nebevî idi.', 'Müslümanların ilk kıblesi Mescid-i Aksâ idi', ['İlk kıble Uhud dağıydı', 'Müslümanların hiç kıblesi olmadı', 'İlk kıble Taif’ti'], 'İlk kıble Mescid-i Aksâ, sonra Kâbe oldu.'),
 ('es', 7, 'ch_es_veda_mekke', 'Veda Hutbesi', 'h', 'Veda Hutbesi Medine’de Mescid-i Nebevî’de okundu.', 'Veda Hutbesi’nin önemli bir kısmı Arafat’ta okundu', ['Veda Hutbesi hiç okunmadı', 'Veda Hutbesi Taif’te okundu', 'Veda Hutbesi Uhud’da okundu'], 'Veda Haccı sırasında Arafat’ta okundu.'),
 ('pr', 7, 'ch_pr_muahat', 'Kardeşlik', 'm', 'Hz. Peygamber’in ensar ile muhaciri kardeş yapmasına ___ denir.', 'muâhât', 'Muâhât, kardeşleştirme demektir.'),
 ('pr', 7, 'ch_pr_ridvan', 'Ağaç altındaki biat', 'h', 'Hudeybiye’de ağacın altında yapılan biata ___ biatı denir.', 'Rıdvan', 'Fetih 48:18.'),
 ('pr', 7, 'ch_pr_hamza', 'Uhud şehidi', 'm', 'Uhud’da şehit düşen Hz. Peygamber’in amcası Hz. ___ dır.', 'Hamza', 'Hz. Hamza “şehitlerin efendisi” olarak anılır.'),
 ('mc', 7, 'ch_sira', 'Kronoloji', 'h', 'Aşağıdaki olaylardan hangisi en son yaşanmıştır?', 'Veda Haccı', ['Bedir savaşı', 'Hudeybiye Antlaşması', 'Mekke’nin fethi'], 'Sıra: Bedir (2), Hudeybiye (6), Mekke’nin fethi (8), Veda Haccı (10).'),
 ('mc', 7, 'ch_af_ayet', 'Fetihteki söz', 'h', 'Hz. Peygamber fetih günü Mekkelilere hangi peygamberin kardeşlerine söylediği sözle hitap etti?', 'Hz. Yûsuf’un', ['Hz. Nuh’un', 'Hz. Musa’nın', 'Hz. İsa’nın'], '“Bugün size kınama yok” sözü Hz. Yûsuf’un kardeşlerine söylediği sözdür (Yûsuf 12:92).'),
 ('mt', 7, 'ch_mt_kisi', 'Kişiler', 'm', 'Kişileri olaylarla eşleştir:', [('Selmân-ı Fârisî', 'Hendek fikri'), ('Bilâl', 'İlk ezan'), ('Ebû Eyyûb el-Ensârî', 'Peygamber’i evinde misafir etmesi'), ('Abdurrahman b. Avf', '“Bana çarşının yolunu göster”')], 'Medine döneminin önemli isimleri.'),
 ('mt', 7, 'ch_mt_yer', 'Yerler', 'h', 'Yerleri olaylarla eşleştir:', [('Kuba', 'İlk mescit'), ('Kıbleteyn', 'Kıblenin değiştiği mescit'), ('Arafat', 'Veda Hutbesi'), ('Hudeybiye', 'On yıllık barış antlaşması')], 'Siyerdeki önemli yerler.'),
 ('sc', 7, 'ch_soz', 'Söz tutmak', 'm', 'Kardeşine bir hafta boyunca oyuncağını ödünç vereceğine söz verdin ama şimdi vazgeçmek istiyorsun. Hudeybiye örneğine göre ne yapmalısın?', 'Sözünü tutup sabretmek', ['Sözünü hemen bozmak', 'Sözü hiç vermemiş gibi davranmak', 'Kardeşini suçlamak'], 'Hz. Peygamber ağır görünen şartlara rağmen sözünü tuttu.'),
 ('tf', 7, 'ch_tf_ravza', 'Kabri', 'm', 'Hz. Peygamber’in kabri Medine’dedir.', True, 'Mescid-i Nebevî’nin içinde, Hz. Âişe’nin odasındadır.'),
